<?php
require_once 'functions.php'; require_admin(); $error=''; $id=(int)($_GET['id']??$_POST['case_id']??0); $existing=null;
if($id){$q=$pdo->prepare('SELECT * FROM cases WHERE case_id=?');$q->execute([$id]);$existing=$q->fetch();if(!$existing){http_response_code(404);exit('Case not found.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $sid=(int)($_POST['student_id']??0);$vid=(int)($_POST['violation_id']??0);$date=$_POST['incident_date']??'';$sanction=trim($_POST['sanction']??'');$status=$_POST['status']??'Pending';$remarks=trim($_POST['remarks']??'');$allowed=['Pending','Under Review','Resolved','Dismissed'];
 if(!$sid||!$vid||!$date||!$sanction||!in_array($status,$allowed,true))$error='Please complete all required fields.';
 else{$q=$pdo->prepare('SELECT COUNT(*) FROM students WHERE student_id=?');$q->execute([$sid]);$q2=$pdo->prepare('SELECT COUNT(*) FROM violations WHERE violation_id=?');$q2->execute([$vid]);if(!$q->fetchColumn()||!$q2->fetchColumn())$error='Choose a valid student and violation.';else{
 if($id){$q=$pdo->prepare('UPDATE cases SET student_id=?,violation_id=?,incident_date=?,remarks=?,sanction=?,status=? WHERE case_id=?');$q->execute([$sid,$vid,$date,$remarks,$sanction,$status,$id]);log_action($pdo,'Updated case','Case Management','Case ID '.$id.'; status='.$status);}
 else{$q=$pdo->prepare('INSERT INTO cases (student_id,violation_id,reported_by,incident_date,remarks,sanction,status) VALUES (?,?,?,?,?,?,?)');$q->execute([$sid,$vid,current_user()['user_id'],$date,$remarks,$sanction,$status]);$id=(int)$pdo->lastInsertId();log_action($pdo,'Created case','Case Management','Case ID '.$id);}
 header('Location: records.php?saved=1');exit;}}}
$students=$pdo->query("SELECT student_id,student_number,CONCAT(first_name,' ',last_name) full_name FROM students ORDER BY last_name")->fetchAll();$violations=$pdo->query('SELECT violation_id,violation_name,default_sanction FROM violations ORDER BY violation_name')->fetchAll();$val=function($k,$d='')use($existing){return $_POST[$k]??($existing[$k]??$d);};page_header($id?'Edit Case':'Add Case'); ?>
<h1><?=$id?'Edit Disciplinary Case #'.(int)$id:'Add Disciplinary Case'?></h1><p class="muted">Manage incident details, sanctions, and case status.</p><section class="panel form-panel"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<form method="post"><input type="hidden" name="case_id" value="<?=$id?>"><label>Student</label><select name="student_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['student_id']?>" <?=((string)$val('student_id')===(string)$s['student_id'])?'selected':''?>><?=e($s['student_number'].' — '.$s['full_name'])?></option><?php endforeach;?></select>
<label>Violation</label><select name="violation_id" id="violation" required><option value="">Select violation</option><?php foreach($violations as $v):?><option value="<?=$v['violation_id']?>" data-sanction="<?=e($v['default_sanction'])?>" <?=((string)$val('violation_id')===(string)$v['violation_id'])?'selected':''?>><?=e($v['violation_name'])?></option><?php endforeach;?></select>
<label>Incident Date</label><input type="date" name="incident_date" required value="<?=e($val('incident_date',date('Y-m-d')))?>"><label>Sanction</label><input name="sanction" id="sanction" required maxlength="160" value="<?=e($val('sanction'))?>"><label>Case Status</label><select name="status"><?php foreach(['Pending','Under Review','Resolved','Dismissed'] as $s):?><option <?=($val('status','Pending')===$s)?'selected':''?>><?=$s?></option><?php endforeach;?></select><label>Remarks</label><textarea name="remarks" rows="4"><?=e($val('remarks'))?></textarea><button class="btn primary" type="submit"><?=$id?'Update Case':'Save Case'?></button> <a class="btn" href="records.php">Cancel</a></form></section>
<script>document.getElementById('violation').addEventListener('change',function(){const o=this.options[this.selectedIndex];if(o.dataset.sanction)document.getElementById('sanction').value=o.dataset.sanction;});</script><?php page_footer();?>